/**
 * @name data-table
 * @description Powerful table and datagrids built using TanStack Table. Supports sorting, filtering, pagination, column visibility, and row selection.
 * @dependencies @tanstack/react-table lucide-react
 * @type registry:ui
 */
"use client";

import * as React from "react";
import {
  type ColumnDef,
  type ColumnFiltersState,
  type ExpandedState,
  type Row,
  type RowData,
  type SortingState,
  type VisibilityState,
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";

declare module "@tanstack/react-table" {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface ColumnMeta<TData extends RowData, TValue> {
    className?: string;
  }
}
import { ArrowUpDown, ChevronDown, MoreHorizontal } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

// ─── DataTable ────────────────────────────────────────────────────────────────

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  /** Key of the column to use for the filter input. Defaults to the first string column. */
  filterColumn?: string;
  /** Placeholder for the filter input */
  filterPlaceholder?: string;
  /** Show vertical borders between cells */
  cellBorder?: boolean;
  /** Reduce cell padding for a compact layout */
  dense?: boolean;
  /** Let columns size to their content instead of stretching to full width */
  autoWidth?: boolean;
  /** Render expanded content below a row. Pair with a toggle column that calls row.getToggleExpandedHandler(). */
  renderExpandedRow?: (row: Row<TData>) => React.ReactNode;
  /** Hide the filter/column toolbar. Useful for nested sub-tables. */
  hideToolbar?: boolean;
  /** Allow columns to be reordered by dragging their headers. */
  movableColumns?: boolean;
  className?: string;
}

function DataTable<TData, TValue>({
  columns,
  data,
  filterColumn,
  filterPlaceholder = "Filter...",
  cellBorder = false,
  dense = false,
  autoWidth = false,
  renderExpandedRow,
  hideToolbar = false,
  movableColumns = false,
  className,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(
    []
  );
  const [columnVisibility, setColumnVisibility] =
    React.useState<VisibilityState>({});
  const [rowSelection, setRowSelection] = React.useState({});
  const [expanded, setExpanded] = React.useState<ExpandedState>({});
  const dragColumnId = React.useRef<string | null>(null);
  const [columnOrder, setColumnOrder] = React.useState<string[]>(() =>
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    columns.map((c) => (c as any).id ?? String((c as any).accessorKey))
  );

  // eslint-disable-next-line react-hooks/incompatible-library
  const table = useReactTable({
    data,
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    onExpandedChange: setExpanded,
    getRowCanExpand: renderExpandedRow ? () => true : undefined,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    ...(movableColumns && { onColumnOrderChange: setColumnOrder }),
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
      expanded,
      ...(movableColumns && { columnOrder }),
    },
  });

  // Determine filter column: use the provided prop, or the first filterable column
  const activeFilterColumn =
    filterColumn ?? table.getAllColumns().find((c) => c.getCanFilter())?.id;

  return (
    <div data-slot="data-table" className={cn("w-full", className)}>
      {/* Toolbar */}
      {!hideToolbar && (
      <div className="flex items-center gap-2 py-4">
        {activeFilterColumn && (
          <Input
            placeholder={filterPlaceholder}
            value={
              (table
                .getColumn(activeFilterColumn)
                ?.getFilterValue() as string) ?? ""
            }
            onChange={(event) =>
              table
                .getColumn(activeFilterColumn)
                ?.setFilterValue(event.target.value)
            }
            className="max-w-sm"
          />
        )}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" className="ml-auto">
              Columns <ChevronDown />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {table
              .getAllColumns()
              .filter((column) => column.getCanHide())
              .map((column) => (
                <DropdownMenuCheckboxItem
                  key={column.id}
                  className="capitalize"
                  checked={column.getIsVisible()}
                  onCheckedChange={(value) =>
                    column.toggleVisibility(!!value)
                  }
                >
                  {column.id}
                </DropdownMenuCheckboxItem>
              ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      )}

      {/* Table */}
      <div className={cn(
        "overflow-hidden rounded-md border",
        "[&_th:first-child:not(:has([data-slot=checkbox]))_[data-slot=button]]:-ms-1",
        "[&_th:not(:first-child)_[data-slot=button]]:-ms-3",
        cellBorder && "[&_td:not(:last-child)]:border-r [&_th:not(:last-child)]:border-r",
        dense && "[&_td]:py-1.5 [&_th]:h-8 [&_th]:py-0",
        autoWidth && "w-fit [&_table]:w-auto"
      )}>
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    draggable={movableColumns || undefined}
                    onDragStart={movableColumns ? () => { dragColumnId.current = header.id; } : undefined}
                    onDragOver={movableColumns ? (e) => { e.preventDefault(); } : undefined}
                    onDrop={movableColumns ? () => {
                      const from = dragColumnId.current;
                      dragColumnId.current = null;
                      if (!from || from === header.id) return;
                      setColumnOrder((prev) => {
                        const order = prev.length ? [...prev] : table.getAllLeafColumns().map((c) => c.id);
                        const fi = order.indexOf(from);
                        const ti = order.indexOf(header.id);
                        if (fi === -1 || ti === -1) return prev;
                        order.splice(fi, 1);
                        order.splice(ti, 0, from);
                        return order;
                      });
                    } : undefined}
                    className={cn(
                      header.column.columnDef.meta?.className,
                      movableColumns && "cursor-grab select-none",
                    )}
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <React.Fragment key={row.id}>
                  <TableRow
                    data-state={row.getIsSelected() && "selected"}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell
                        key={cell.id}
                        className={cn(cell.column.columnDef.meta?.className)}
                      >
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext()
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                  {row.getIsExpanded() && renderExpandedRow && (
                    <TableRow className="hover:bg-transparent">
                      <TableCell colSpan={row.getVisibleCells().length} className="p-0">
                        {renderExpandedRow(row)}
                      </TableCell>
                    </TableRow>
                  )}
                </React.Fragment>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
          {table.getFooterGroups().some((fg) =>
            fg.headers.some((h) => h.column.columnDef.footer)
          ) && (
            <TableFooter>
              {table.getFooterGroups().map((footerGroup) => (
                <TableRow key={footerGroup.id}>
                  {footerGroup.headers.map((footer) => (
                    <TableCell
                      key={footer.id}
                      colSpan={footer.colSpan}
                      className={cn(footer.column.columnDef.meta?.className)}
                    >
                      {footer.isPlaceholder
                        ? null
                        : flexRender(
                            footer.column.columnDef.footer,
                            footer.getContext()
                          )}
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableFooter>
          )}
        </Table>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between py-4">
        <div className="text-sm text-muted-foreground">
          {table.getFilteredSelectedRowModel().rows.length} of{" "}
          {table.getFilteredRowModel().rows.length} row(s) selected.
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

// ─── DataTableColumnHeader ────────────────────────────────────────────────────

function DataTableColumnHeader<TValue>({
  column,
  title,
  icon,
  className,
}: {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  column: import("@tanstack/react-table").Column<any, TValue>;
  title: string;
  icon?: React.ReactNode;
  className?: string;
}) {
  if (!column.getCanSort()) {
    return (
      <div className={cn("flex items-center gap-1.5", className)}>
        {icon && <span className="shrink-0 text-muted-foreground [&_svg]:size-3.5">{icon}</span>}
        {title}
      </div>
    );
  }

  return (
    <Button
      variant="ghost"
      size="sm"
      className={cn(className)}
      onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
    >
      {icon && <span className="shrink-0 text-muted-foreground [&_svg]:size-3.5">{icon}</span>}
      {title}
      <ArrowUpDown className="ml-2" />
    </Button>
  );
}

// ─── DataTableRowActions ──────────────────────────────────────────────────────

interface DataTableRowActionsProps {
  children?: React.ReactNode;
}

function DataTableRowActions({ children }: DataTableRowActionsProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" className="size-10 p-0">
          <span className="sr-only">Open menu</span>
          <MoreHorizontal />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuLabel>Actions</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {children ?? (
          <>
            <DropdownMenuItem>View</DropdownMenuItem>
            <DropdownMenuItem>Edit</DropdownMenuItem>
            <DropdownMenuItem className="text-destructive">
              Delete
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export {
  DataTable,
  DataTableColumnHeader,
  DataTableRowActions,
  DropdownMenuItem,
  DropdownMenuSeparator,
  Checkbox,
};
export type { DataTableProps };
